import json

transcript_path = "/Users/jsriverab/.gemini/antigravity/brain/ff92a427-3657-4ec1-aecb-e7683ff23de6/.system_generated/logs/transcript_full.jsonl"

with open(transcript_path, "r", encoding="utf-8") as f:
    for line in f:
        try:
            step = json.loads(line)
            # dump any step of type VIEW_FILE or write_to_file that contains SITE_META
            step_str = json.dumps(step)
            if "SITE_META" in step_str:
                print(f"Step {step.get('step_index')}: type={step.get('type')}, source={step.get('source')}")
        except Exception as e:
            pass
